UPDATE HR_UNIFORM_ITEM
   SET ACTIVITY    = -1,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR}
 WHERE ITEM_NO = #{itemNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.select:
SELECT COUNT(*)
  FROM HR_UNIFORM_ITEM I
 WHERE I.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
   AND I.ACTIVITY IN (0, 1)
   AND CONVERTTOUNSIGN(UPPER(TRIM(I.ITEM_NAME))) = CONVERTTOUNSIGN(UPPER(TRIM(#{itemName, jdbcType=VARCHAR})))

   AND I.ITEM_NO <> #{excludeItemNo, jdbcType=NUMERIC}

SELECT * FROM (
    SELECT INNER_Q.*, ROWNUM AS RN FROM (


         ORDER BY C.CHANGE_DATE DESC, HE.EMPID, C.CHANGE_NO DESC
    ) INNER_Q
    WHERE ROWNUM <= #{start, jdbcType=NUMERIC} + #{length, jdbcType=NUMERIC}
) WHERE RN > #{start, jdbcType=NUMERIC}

SELECT C.PERSON_ID, TO_CHAR(C.CHANGE_DATE, 'YYYY-MM') AS CHANGE_MONTH, SUM(NVL(D.QUANTITY, 0)) AS TOTAL_QTY FROM HR_UNIFORM_CHANGE C LEFT JOIN HR_UNIFORM_CHANGE_DETAIL D ON D.CHANGE_NO = C.CHANGE_NO WHERE C.ACTIVITY = 1 AND C.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND C.CHANGE_DATE >= ADD_MONTHS(TO_DATE(#{month, jdbcType=VARCHAR}, 'YYYY-MM'), 0 - #{intervalMonths, jdbcType=NUMERIC}) AND C.CHANGE_DATE < TO_DATE(#{month, jdbcType=VARCHAR}, 'YYYY-MM') AND C.PERSON_ID IN
#{pid, jdbcType=VARCHAR}
GROUP BY C.PERSON_ID, TO_CHAR(C.CHANGE_DATE, 'YYYY-MM')

SELECT TO_CHAR(MAX(C.CHANGE_DATE), 'DD/MM/YYYY')
  FROM HR_UNIFORM_CHANGE C
 WHERE C.ACTIVITY  = 1
   AND C.CPNY_ID   = #{cpnyId, jdbcType=VARCHAR}
   AND C.PERSON_ID = #{personId, jdbcType=VARCHAR}
   AND C.CHANGE_DATE > ADD_MONTHS(TO_DATE(#{changeDate, jdbcType=VARCHAR}, 'DD/MM/YYYY'), 0 - #{intervalMonths, jdbcType=NUMERIC})
   AND C.CHANGE_DATE < ADD_MONTHS(TO_DATE(#{changeDate, jdbcType=VARCHAR}, 'DD/MM/YYYY'), #{intervalMonths, jdbcType=NUMERIC})

   AND C.CHANGE_NO <> #{excludeChangeNo, jdbcType=NUMERIC}

