INSERT INTO HR_UNIFORM_CHANGE (
    CHANGE_NO, CPNY_ID, PERSON_ID, CHANGE_DATE, REASON, REMARK, ACTIVITY,
    CREATE_DATE, CREATED_BY, CREATE_IP, UPDATE_DATE, UPDATED_BY, UPDATE_IP
) VALUES (
    #{changeNo, jdbcType=NUMERIC}, #{cpnyId, jdbcType=VARCHAR}, #{personId, jdbcType=VARCHAR},
    TO_DATE(#{changeDate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
    #{reason, jdbcType=VARCHAR}, #{remark, jdbcType=VARCHAR}, 1,
    SYSDATE, #{adminID, jdbcType=VARCHAR}, #{adminIP, jdbcType=VARCHAR},
    SYSDATE, #{adminID, jdbcType=VARCHAR}, #{adminIP, jdbcType=VARCHAR}
)

mapper.update:
UPDATE HR_UNIFORM_CHANGE
   SET CHANGE_DATE = TO_DATE(#{changeDate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
       REASON      = #{reason, jdbcType=VARCHAR},
       REMARK      = #{remark, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATE_IP   = #{adminIP, jdbcType=VARCHAR}
 WHERE CHANGE_NO = #{changeNo, jdbcType=NUMERIC}
   AND CPNY_ID   = #{cpnyId, jdbcType=VARCHAR}
   AND ACTIVITY  = 1

UPDATE HR_UNIFORM_CHANGE
   SET ACTIVITY    = 0,
       UPDATE_DATE = SYSDATE,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATE_IP   = #{adminIP, jdbcType=VARCHAR}
 WHERE CHANGE_NO = #{changeNo, jdbcType=NUMERIC}
   AND CPNY_ID   = #{cpnyId, jdbcType=VARCHAR}
